ALTER TABLE public.client_packages ADD COLUMN price_amount numeric(12,2) CHECK(price_amount IS NULL OR price_amount>=0), ADD COLUMN purchased_on date, ADD COLUMN balance_as_of date, ADD COLUMN reconciliation_notes text NOT NULL DEFAULT '';
CREATE TABLE public.client_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trainer_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE,package_id uuid NOT NULL REFERENCES public.client_packages(id) ON DELETE RESTRICT,amount numeric(12,2) NOT NULL CHECK(amount>0),paid_on date,paid_month text NOT NULL CHECK(paid_month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),method text NOT NULL DEFAULT 'unknown' CHECK(method IN('unknown','cash','bank_transfer','card','other')),reference text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',voided_at timestamptz,void_reason text NOT NULL DEFAULT '',revision integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.monthly_sales_totals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),trainer_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,month text NOT NULL CHECK(month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),received_total numeric(12,2) NOT NULL CHECK(received_total>=0),notes text NOT NULL DEFAULT '',UNIQUE(trainer_id,month));
CREATE INDEX client_payments_owner_month_idx ON public.client_payments(trainer_id,paid_month);
CREATE INDEX client_payments_client_idx ON public.client_payments(client_id);
CREATE INDEX client_payments_package_idx ON public.client_payments(package_id);
ALTER TABLE public.client_payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.monthly_sales_totals ENABLE ROW LEVEL SECURITY;
CREATE POLICY payments_owner_all ON public.client_payments FOR ALL TO authenticated USING((SELECT auth.uid())=trainer_id) WITH CHECK((SELECT auth.uid())=trainer_id);
CREATE POLICY sales_totals_owner_all ON public.monthly_sales_totals FOR ALL TO authenticated USING((SELECT auth.uid())=trainer_id) WITH CHECK((SELECT auth.uid())=trainer_id);
REVOKE ALL ON public.client_payments,public.monthly_sales_totals FROM PUBLIC,anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.client_payments,public.monthly_sales_totals TO authenticated;
CREATE FUNCTION public.crm_guard_payment() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE p public.client_packages; received numeric; restoring boolean;
BEGIN
 IF TG_OP='DELETE' THEN IF coalesce(current_setting('crm.restore_mode',true),'')<>'on' THEN RAISE EXCEPTION 'Void payments to preserve history'; END IF; RETURN OLD; END IF;
 SELECT * INTO p FROM public.client_packages WHERE id=NEW.package_id FOR UPDATE;
 IF NOT FOUND OR p.client_id<>NEW.client_id OR p.trainer_id<>NEW.trainer_id OR (auth.uid() IS NOT NULL AND NEW.trainer_id<>auth.uid()) THEN RAISE EXCEPTION 'Package is not available to this account'; END IF;
 restoring=coalesce(current_setting('crm.restore_mode',true),'')='on';
 IF NEW.paid_on IS NOT NULL THEN NEW.paid_month=to_char(NEW.paid_on,'YYYY-MM'); END IF;
 IF NEW.paid_on>(now() AT TIME ZONE 'Asia/Dubai')::date OR NEW.paid_month>to_char(now() AT TIME ZONE 'Asia/Dubai','YYYY-MM') THEN RAISE EXCEPTION 'Payment cannot be in the future'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (NEW.trainer_id,NEW.client_id,NEW.package_id) IS DISTINCT FROM (OLD.trainer_id,OLD.client_id,OLD.package_id) THEN RAISE EXCEPTION 'Payment ownership cannot change'; END IF;
  IF NOT restoring AND (NEW.amount,NEW.paid_on,NEW.paid_month,NEW.method,NEW.reference,NEW.notes) IS DISTINCT FROM (OLD.amount,OLD.paid_on,OLD.paid_month,OLD.method,OLD.reference,OLD.notes) THEN RAISE EXCEPTION 'Void the payment and record a correction'; END IF;
  IF OLD.voided_at IS NOT NULL AND NEW.voided_at IS NULL AND NOT restoring THEN RAISE EXCEPTION 'Voided payments cannot be reactivated'; END IF; NEW.revision=OLD.revision+1;
 END IF;
 IF NEW.voided_at IS NOT NULL AND length(btrim(NEW.void_reason))<3 THEN RAISE EXCEPTION 'Enter a reason for voiding this payment'; END IF;
 SELECT coalesce(sum(amount),0) INTO received FROM public.client_payments WHERE package_id=NEW.package_id AND id<>NEW.id AND voided_at IS NULL;
 IF NOT restoring AND NEW.voided_at IS NULL AND p.price_amount IS NOT NULL AND received+NEW.amount>p.price_amount THEN RAISE EXCEPTION 'Payment exceeds the outstanding package amount'; END IF;
 NEW.updated_at=now(); RETURN NEW;
END; $$;
CREATE TRIGGER crm_payment_guard BEFORE INSERT OR UPDATE OR DELETE ON public.client_payments FOR EACH ROW EXECUTE FUNCTION public.crm_guard_payment();
CREATE FUNCTION public.crm_guard_purchase() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ BEGIN
 IF NEW.purchased_on>(now() AT TIME ZONE 'Asia/Dubai')::date OR NEW.balance_as_of>(now() AT TIME ZONE 'Asia/Dubai')::date THEN RAISE EXCEPTION 'Purchase or balance date cannot be in the future'; END IF;
 IF coalesce(current_setting('crm.restore_mode',true),'')<>'on' AND NEW.price_amount IS NOT NULL AND NEW.price_amount<(SELECT coalesce(sum(amount),0) FROM public.client_payments WHERE package_id=NEW.id AND voided_at IS NULL) THEN RAISE EXCEPTION 'Price cannot be below recorded payments'; END IF; RETURN NEW;
END; $$;
CREATE TRIGGER crm_purchase_guard BEFORE INSERT OR UPDATE ON public.client_packages FOR EACH ROW EXECUTE FUNCTION public.crm_guard_purchase();
CREATE OR REPLACE FUNCTION public.crm_update_package(p_id uuid,p_revision integer,p_values jsonb) RETURNS public.client_packages LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE p public.client_packages; BEGIN
 UPDATE public.client_packages SET name=p_values->>'name',purchased=(p_values->>'purchased')::integer,opening_consumed=(p_values->>'opening_consumed')::integer,start_date=nullif(p_values->>'start_date','')::date,expiry_date=nullif(p_values->>'expiry_date','')::date,archived=coalesce((p_values->>'archived')::boolean,false),price_amount=CASE WHEN p_values?'price_amount' THEN nullif(p_values->>'price_amount','')::numeric ELSE price_amount END,purchased_on=CASE WHEN p_values?'purchased_on' THEN nullif(p_values->>'purchased_on','')::date ELSE purchased_on END,balance_as_of=CASE WHEN p_values?'balance_as_of' THEN nullif(p_values->>'balance_as_of','')::date ELSE balance_as_of END,reconciliation_notes=coalesce(p_values->>'reconciliation_notes',reconciliation_notes) WHERE id=p_id AND revision=p_revision RETURNING * INTO p;
 IF NOT FOUND THEN RAISE EXCEPTION 'Package changed on another device. Refresh before trying again'; END IF; RETURN p; END; $$;
CREATE FUNCTION public.crm_save_payment(p_id uuid,p_values jsonb) RETURNS public.client_payments LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE p public.client_payments; BEGIN
 PERFORM 1 FROM public.client_packages WHERE id=(p_values->>'package_id')::uuid FOR UPDATE;
 SELECT * INTO p FROM public.client_payments WHERE id=p_id;
 IF FOUND THEN
 IF (p.client_id,p.package_id,p.amount,p.paid_on,p.paid_month,p.method,p.reference,p.notes) IS DISTINCT FROM ((p_values->>'client_id')::uuid,(p_values->>'package_id')::uuid,(p_values->>'amount')::numeric,nullif(p_values->>'paid_on','')::date,coalesce(to_char(nullif(p_values->>'paid_on','')::date,'YYYY-MM'),p_values->>'paid_month'),coalesce(p_values->>'method','unknown'),coalesce(p_values->>'reference',''),coalesce(p_values->>'notes','')) THEN RAISE EXCEPTION 'Payment request already used with different details'; END IF; RETURN p; END IF;
 INSERT INTO public.client_payments(id,client_id,package_id,amount,paid_on,paid_month,method,reference,notes) VALUES(p_id,(p_values->>'client_id')::uuid,(p_values->>'package_id')::uuid,(p_values->>'amount')::numeric,nullif(p_values->>'paid_on','')::date,coalesce(p_values->>'paid_month',''),coalesce(p_values->>'method','unknown'),coalesce(p_values->>'reference',''),coalesce(p_values->>'notes','')) RETURNING * INTO p; RETURN p; END; $$;
CREATE FUNCTION public.crm_void_payment(p_id uuid,p_revision integer,p_reason text) RETURNS public.client_payments LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE p public.client_payments; BEGIN UPDATE public.client_payments SET voided_at=now(),void_reason=p_reason WHERE id=p_id AND revision=p_revision AND voided_at IS NULL RETURNING * INTO p; IF NOT FOUND THEN RAISE EXCEPTION 'Payment changed or was already voided. Refresh before trying again'; END IF; RETURN p; END; $$;
CREATE FUNCTION public.crm_record_attendance(p_id uuid,p_values jsonb) RETURNS public.sessions LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE s public.sessions; BEGIN
 PERFORM 1 FROM public.clients WHERE id=(p_values->>'client_id')::uuid FOR UPDATE; SELECT * INTO s FROM public.sessions WHERE id=p_id;
 IF FOUND THEN IF (s.client_id,s.date,s.session_time,s.attendance_status,s.session_note) IS DISTINCT FROM ((p_values->>'client_id')::uuid,(p_values->>'date')::date,nullif(p_values->>'session_time','')::time,coalesce(p_values->>'attendance_status','attended'),coalesce(p_values->>'session_note','')) THEN RAISE EXCEPTION 'Attendance request already used with different details'; END IF; RETURN s; END IF;
 INSERT INTO public.sessions(id,client_id,date,session_time,attendance_status,charge_session,package_id,session_note) VALUES(p_id,(p_values->>'client_id')::uuid,(p_values->>'date')::date,nullif(p_values->>'session_time','')::time,coalesce(p_values->>'attendance_status','attended'),coalesce((p_values->>'charge_session')::boolean,false),nullif(p_values->>'package_id','')::uuid,coalesce(p_values->>'session_note','')) RETURNING * INTO s; RETURN s; END; $$;
CREATE FUNCTION public.crm_append_client_note(p_id uuid,p_expected_updated_at timestamptz,p_note text) RETURNS public.clients LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE c public.clients; BEGIN IF length(btrim(p_note)) NOT BETWEEN 1 AND 6000 THEN RAISE EXCEPTION 'Note must contain 1–6000 characters'; END IF; UPDATE public.clients SET general_notes=concat_ws(E'\n\n',nullif(general_notes,''),to_char(now() AT TIME ZONE 'Asia/Dubai','YYYY-MM-DD HH24:MI')||' · '||p_note) WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO c; IF NOT FOUND THEN RAISE EXCEPTION 'Client changed. Read the latest profile before adding this note'; END IF; RETURN c; END; $$;
CREATE FUNCTION public.crm_reconcile_attendance(p_package uuid,p_revision integer,p_ids uuid[],p_note text) RETURNS public.client_packages LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE p public.client_packages; n integer; latest date; BEGIN
 SELECT * INTO p FROM public.client_packages WHERE id=p_package AND revision=p_revision FOR UPDATE; IF NOT FOUND OR p.balance_as_of IS NULL THEN RAISE EXCEPTION 'Refresh the package and enter its confirmed balance date first'; END IF;
 SELECT count(*),max(date) INTO n,latest FROM public.sessions WHERE id=ANY(p_ids) AND client_id=p.client_id AND trainer_id=auth.uid() AND date>p.balance_as_of AND NOT charge_session AND voided_at IS NULL AND attendance_status='attended' AND session_note LIKE 'Imported from confirmed ChatGPT attendance history%';
 IF n=0 OR n<>cardinality(p_ids) OR length(btrim(p_note))<3 THEN RAISE EXCEPTION 'Select unreconciled imported visits after the confirmed balance date and give a reason'; END IF;
 IF public.crm_package_remaining(p.id)<n THEN RAISE EXCEPTION 'Not enough sessions to reconcile these visits'; END IF;
 PERFORM set_config('crm.restore_mode','on',true);
 UPDATE public.sessions SET charge_session=true,package_id=p.id,session_note=session_note||E'\nReconciled: '||p_note,revision=revision+1 WHERE id=ANY(p_ids) AND trainer_id=auth.uid();
 PERFORM set_config('crm.restore_mode','off',true);
 UPDATE public.client_packages SET balance_as_of=latest,reconciliation_notes=p_note WHERE id=p.id RETURNING * INTO p; RETURN p; END; $$;
ALTER FUNCTION public.crm_restore_backup(jsonb,text) RENAME TO crm_restore_backup_v4;
CREATE FUNCTION public.crm_restore_backup(p_data jsonb,p_mode text DEFAULT 'merge') RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE r jsonb; v jsonb; existing jsonb; n integer=0; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in before restoring'; END IF;
 IF p_mode='replace' AND (NOT p_data?'client_payments' OR NOT p_data?'monthly_sales_totals') THEN RAISE EXCEPTION 'Complete backup including payments required for replacement; use merge for older backups'; END IF;
 IF p_data?'client_payments' AND jsonb_typeof(p_data->'client_payments')<>'array' THEN RAISE EXCEPTION 'Invalid payments collection'; END IF;
 IF p_data?'monthly_sales_totals' AND jsonb_typeof(p_data->'monthly_sales_totals')<>'array' THEN RAISE EXCEPTION 'Invalid monthly totals collection'; END IF;
 PERFORM set_config('crm.restore_mode','on',true); IF p_mode='replace' THEN DELETE FROM public.client_payments WHERE trainer_id=auth.uid(); DELETE FROM public.monthly_sales_totals WHERE trainer_id=auth.uid(); END IF;
 r=public.crm_restore_backup_v4(p_data,p_mode); PERFORM set_config('crm.restore_mode','on',true);
 FOR v IN SELECT value FROM jsonb_array_elements(coalesce(p_data->'client_payments','[]'::jsonb)) LOOP
 SELECT to_jsonb(p) INTO existing FROM public.client_payments p WHERE id=(v->>'id')::uuid;
 v=jsonb_build_object('method','unknown','reference','','notes','','void_reason','','revision',0,'created_at',now(),'updated_at',now())||coalesce(existing,'{}'::jsonb)||v||jsonb_build_object('trainer_id',auth.uid());
 INSERT INTO public.client_payments SELECT * FROM jsonb_populate_record(NULL::public.client_payments,v) ON CONFLICT(id) DO UPDATE SET amount=EXCLUDED.amount,paid_on=EXCLUDED.paid_on,paid_month=EXCLUDED.paid_month,method=EXCLUDED.method,reference=EXCLUDED.reference,notes=EXCLUDED.notes,voided_at=EXCLUDED.voided_at,void_reason=EXCLUDED.void_reason; n=n+1; END LOOP;
 FOR v IN SELECT value FROM jsonb_array_elements(coalesce(p_data->'monthly_sales_totals','[]'::jsonb)) LOOP INSERT INTO public.monthly_sales_totals(id,trainer_id,month,received_total,notes) VALUES((v->>'id')::uuid,auth.uid(),v->>'month',(v->>'received_total')::numeric,coalesce(v->>'notes','')) ON CONFLICT(id) DO UPDATE SET month=EXCLUDED.month,received_total=EXCLUDED.received_total,notes=EXCLUDED.notes; END LOOP;
 IF EXISTS(SELECT 1 FROM public.client_packages p WHERE p.trainer_id=auth.uid() AND p.price_amount IS NOT NULL AND p.price_amount<(SELECT coalesce(sum(amount),0) FROM public.client_payments WHERE package_id=p.id AND voided_at IS NULL)) THEN RAISE EXCEPTION 'Backup payments exceed a package price; no changes were saved'; END IF;
 PERFORM set_config('crm.restore_mode','off',true); RETURN r||jsonb_build_object('client_payments',n); END; $$;
REVOKE ALL ON FUNCTION public.crm_guard_payment(),public.crm_guard_purchase(),public.crm_save_payment(uuid,jsonb),public.crm_void_payment(uuid,integer,text),public.crm_record_attendance(uuid,jsonb),public.crm_append_client_note(uuid,timestamptz,text),public.crm_reconcile_attendance(uuid,integer,uuid[],text),public.crm_restore_backup(jsonb,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crm_guard_payment(),public.crm_guard_purchase(),public.crm_save_payment(uuid,jsonb),public.crm_void_payment(uuid,integer,text),public.crm_record_attendance(uuid,jsonb),public.crm_append_client_note(uuid,timestamptz,text),public.crm_reconcile_attendance(uuid,integer,uuid[],text),public.crm_restore_backup(jsonb,text) TO authenticated;
CREATE FUNCTION public.crm_client_summary(p_client uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT jsonb_build_object('client',to_jsonb(c),'packages',(SELECT coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object('remaining',public.crm_package_remaining(p.id))),'[]'::jsonb) FROM public.client_packages p WHERE p.client_id=c.id),'payments',(SELECT coalesce(jsonb_agg(to_jsonb(v)),'[]'::jsonb) FROM(SELECT * FROM public.client_payments WHERE client_id=c.id ORDER BY created_at DESC LIMIT 100)v),'recent_attendance',(SELECT coalesce(jsonb_agg(to_jsonb(v)),'[]'::jsonb) FROM(SELECT id,date,session_time,attendance_status,charge_session,package_id,session_note,voided_at FROM public.sessions WHERE client_id=c.id ORDER BY date DESC,created_at DESC LIMIT 100)v)) FROM public.clients c WHERE c.id=p_client;
$$;
CREATE FUNCTION public.crm_sales_report(p_month text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$ DECLARE itemised numeric; reported numeric; BEGIN
 IF p_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN RAISE EXCEPTION 'Enter a valid receipt month'; END IF;
 SELECT coalesce(sum(amount),0) INTO itemised FROM public.client_payments WHERE paid_month=p_month AND voided_at IS NULL;
 SELECT received_total INTO reported FROM public.monthly_sales_totals WHERE month=p_month;
 RETURN jsonb_build_object('month',p_month,'itemised_received',itemised,'previously_reported_received',reported,'unitemised_gap',CASE WHEN reported IS NULL THEN NULL ELSE greatest(0,reported-itemised) END,'expected_future_renewals',(SELECT coalesce(sum(expected_renewal),0) FROM public.clients WHERE status='active' AND renewal_status NOT IN('deferred','renewed')),'known_outstanding',(SELECT coalesce(sum(greatest(0,p.price_amount-(SELECT coalesce(sum(amount),0) FROM public.client_payments WHERE package_id=p.id AND voided_at IS NULL))),0) FROM public.client_packages p WHERE NOT p.archived AND p.price_amount IS NOT NULL),'coverage','Itemised receipts only; reported totals are compared, not added. Unknown package prices are excluded from outstanding.'); END; $$;
CREATE FUNCTION public.crm_create_purchase(p_id uuid,p_values jsonb) RETURNS public.client_packages LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ DECLARE p public.client_packages; BEGIN
 PERFORM 1 FROM public.clients WHERE id=(p_values->>'client_id')::uuid FOR UPDATE; SELECT * INTO p FROM public.client_packages WHERE id=p_id;
 IF FOUND THEN IF (p.client_id,p.name,p.purchased,p.price_amount,p.purchased_on,p.expiry_date) IS DISTINCT FROM ((p_values->>'client_id')::uuid,p_values->>'name',(p_values->>'purchased')::integer,nullif(p_values->>'price_amount','')::numeric,nullif(p_values->>'purchased_on','')::date,nullif(p_values->>'expiry_date','')::date) THEN RAISE EXCEPTION 'Purchase request already used with different details'; END IF; RETURN p; END IF;
 INSERT INTO public.client_packages(id,client_id,name,purchased,price_amount,purchased_on,expiry_date) VALUES(p_id,(p_values->>'client_id')::uuid,p_values->>'name',(p_values->>'purchased')::integer,nullif(p_values->>'price_amount','')::numeric,nullif(p_values->>'purchased_on','')::date,nullif(p_values->>'expiry_date','')::date) RETURNING * INTO p; RETURN p; END; $$;
REVOKE ALL ON FUNCTION public.crm_client_summary(uuid),public.crm_sales_report(text),public.crm_create_purchase(uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.crm_client_summary(uuid),public.crm_sales_report(text),public.crm_create_purchase(uuid,jsonb) TO authenticated;

